Usage
```ts
import { escapeCss } from "@ende/html/unstable-escape-css";
import { assertEquals } from "@ende/assert";

// Invalid in a CSS selector, even though it's a valid HTML ID
const elementId = "123";
// Unsafe for interpolation
const contentInput = `<!-- '" --></style>`;

const selector = `#${escapeCss(elementId)}`;
const content = `"${escapeCss(contentInput)}"`;

// Usable as a CSS selector
assertEquals(selector, String.raw`#\31 23`);
// Safe for interpolation
assertEquals(content, String.raw`"\<\!--\ \'\"\ --\>\<\/style\>"`);

// Usage
`<style>
 ${selector}::after {
   content: ${content};
 }
</style>`;
```

Escaping a string
```ts
import { escapeJs } from "@ende/html/unstable-escape-js";
import { assertEquals } from "@ende/assert";
const input = "\u2028\u2029</script>";
assertEquals(escapeJs(input), '"\\u2028\\u2029\\u003c/script>"');
```

Escaping an object
```ts
import { escapeJs } from "@ende/html/unstable-escape-js";
import { assertEquals } from "@ende/assert";
const input = {
  "<SCRIPT>": "</script>",
  "<!--": "\u2028\u2029<>",
};
assertEquals(
 escapeJs(input),
 '{"\\u003cSCRIPT>":"\\u003c/script>","\\u003c!--":"\\u2028\\u2029<>"}',
);
```

Interpolating arbitrary data in a script tag
```ts no-assert ignore
// might be nested arbitrarily deeply
declare const data: string | number | Record<string, string> | Record<string, Record<string, string>>;
const scriptHtml = `<script>window.handleData(${escapeJs(data)})</script>`;
```

Interpolating into a JSON script (e.g. importmap)
```ts no-assert ignore
const importMap = { imports: { zod: 'https://esm.sh/v131/zod@3.21.4' } };
const importMapHtml = `<script type="importmap">${escapeJs(importMap)}</script>`;
```

Usage with trusted content
```ts
import { html } from "@ende/html/unstable-html";
import { assertEquals } from "@ende/assert/equals";

const name = "Alice";
const color = "blue";
const htmlContent = html`
  <div>
    <h1>Hello, ${name}!</h1>
    <p style="color: ${color};">Welcome to our site.</p>
  </div>
`;

assertEquals(htmlContent, `
  <div>
    <h1>Hello, Alice!</h1>
    <p style="color: blue;">Welcome to our site.</p>
  </div>
`);
```

Usage with untrusted content that needs to be escaped
```ts
import { html } from "@ende/html/unstable-html";
import { assertEquals } from "@ende/assert/equals";
import { escape } from "@ende/html/entities";

// WARNING: This is vulnerable to XSS attacks!
const userInput = '<script>alert("XSS")</script>';
const unsafeHtml = html`<div>${userInput}</div>`;

const safeHtml = html`<div>${escape(userInput)}</div>`;

assertEquals(unsafeHtml, '<div><script>alert("XSS")</script></div>');
assertEquals(safeHtml, "<div>&lt;script&gt;alert(&quot;XSS&quot;)&lt;/script&gt;</div>");
```

